  End Inside.

  Section J.
      Variables (mm : word -> option byte) (junk : list byte).
      Hypothesis MIm : mem_inv bsegs mm.
      Hypothesis FR : rw_cells bsegs mm (bv_unsigned sp + -64) [CB 8 junk; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
      Hypothesis STm : stk bsegs mm lo (bv_unsigned sp + -64).
      Hypothesis MU : munch [(bv_unsigned sp - RIP_STACK, bv_unsigned sp)] m mm.
      Hypothesis WM : wmono bsegs m mm.
      Hypothesis G1 : rw_cells bsegs mm 1177224 [C8 (Z_to_bv 64 1234872)].
      Hypothesis C1 : rw_cells bsegs mm 1234872 [C8 (Z_to_bv 64 2147450880)].
      Hypothesis G2 : rw_cells bsegs mm 1177232 [C8 (Z_to_bv 64 1238184)].
      Hypothesis G3 : rw_cells bsegs mm 1177240 [C8 (Z_to_bv 64 1238192)].
      Hypothesis G4 : rw_cells bsegs mm 1177248 [C8 (Z_to_bv 64 1238176)].
      Hypothesis C4 : rw_cells bsegs mm 1238176 [C8 (Z_to_bv 64 (2 ^ 47 - 1)); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)].
      Variables (v1 v2 : Z).
      Hypothesis N0 : 0 < n.
      Hypothesis V1 : 0 <= v1 < 8.
      Hypothesis B1 : bytes_at bsegs mm (sh a) [b8 v1].
      Hypothesis OK1 : byte_ok v1 a.
      Hypothesis V2 : 0 <= v2 < 8.
      Hypothesis B2 : bytes_at bsegs mm (sh (a + n - 1)) [b8 v2].
      Hypothesis OK2 : byte_ok v2 (a + n - 1).
      Hypothesis ZB : bytes_at bsegs mm (2147450880 + (a + 7) / 8) (zeros (Z.to_nat ((a + n) / 8 - (a + 7) / 8))).

      Lemma sh_mul8 : forall q, sh (8 * q) = 2147450880 + q.
      Proof. intros q. unfold sh. rewrite ASHADOW_BASE_val, Z.mul_comm, Z.div_mul by lia. reflexivity. Qed.

(* [comment removed for export] *)
      Lemma rip_j4 : forall x1 x5 x11 x12 x13 x14 x15 x16 x17 x18 x20 x21,
        evt bsegs POST (RST 0x076350 x1 x5 (Z_to_bv 64 a) (Z_to_bv 64 n) (Z_to_bv 64 (sh (8 * ((a + n) / 8)))) x11 x12 x13 x14 x15 x16 x17
